class GameState {
public:
    int total;
    GameState(int t = 0) : total(t) {}
    std::vector<int> getLegalMoves() const {
        if (total < 5) return {1, 2};
        return {};
    }
    GameState applyMove(int move) const { return GameState(total + move); }
    bool isTerminal() const { return total >= 5; }
    double getResult() const { return total == 5 ? 1.0 : 0.0; }
};

class MCTSNode : public std::enable_shared_from_this<MCTSNode> {
public:
    GameState state;
    std::weak_ptr<MCTSNode> parent;
    int move;
    std::vector<std::shared_ptr<MCTSNode>> children;
    double wins = 0;
    int visits = 0;
    std::vector<int> untriedMoves;

    MCTSNode(GameState s, std::shared_ptr<MCTSNode> p, int m) 
        : state(s), parent(p), move(m) {
        untriedMoves = s.getLegalMoves();
    }

    std::shared_ptr<MCTSNode> uctSelectChild() {
        double c = 1.41;
        std::shared_ptr<MCTSNode> best = nullptr;
        double bestVal = -1.0;
        for (auto& child : children) {
            double uct = (child->wins / child->visits) + c * std::sqrt(std::log(visits) / child->visits);
            if (uct > bestVal) {
                bestVal = uct;
                best = child;
            }
        }
        return best;
    }

    std::shared_ptr<MCTSNode> expand() {
        int m = untriedMoves.back();
        untriedMoves.pop_back();
        auto child = std::make_shared<MCTSNode>(state.applyMove(m), shared_from_this(), m);
        children.push_back(child);
        return child;
    }

    void backpropagate(double result) {
        visits++;
        wins += result;
        if (auto p = parent.lock()) p->backpropagate(result);
    }
};

int runMCTS(GameState rootState, int iterations) {
    auto root = std::make_shared<MCTSNode>(rootState, nullptr, -1);
    std::random_device rd;
    std::mt19937 gen(rd());

    for (int i = 0; i < iterations; i++) {
        auto node = root;
        GameState state = rootState;

        while (node->untriedMoves.empty() && !node->children.empty()) {
            node = node->uctSelectChild();
            state = state.applyMove(node->move);
        }
        if (!node->untriedMoves.empty()) {
            node = node->expand();
            state = state.applyMove(node->move);
        }
        while (!state.isTerminal()) {
            auto moves = state.getLegalMoves();
            std::uniform_int_distribution<> dis(0, moves.size() - 1);
            state = state.applyMove(moves[dis(gen)]);
        }
        node->backpropagate(state.getResult());
    }

    std::shared_ptr<MCTSNode> bestChild = root->children[0];
    for (auto& child : root->children) {
        if (child->visits > bestChild->visits) bestChild = child;
    }
    return bestChild->move;
}

// --- CI/CD Automated Test ---
int main() {
    int optimalMove = runMCTS(GameState(3), 500);
    if (optimalMove == 2) {
        std::cout << "C++ MCTS Test Passed!\n";
        return 0;
    }
    return 1;
}

import math
import random

class GameState:
    def __init__(self, current_total=0):
        self.current_total = current_total

    def get_legal_moves(self):
        return [1, 2] if self.current_total < 5 else []

    def apply_move(self, move):
        return GameState(self.current_total + move)

    def is_terminal(self):
        return self.current_total >= 5

    def get_result(self):
        # Win if exactly 5, lose if overshoot
        return 1.0 if self.current_total == 5 else 0.0

class MCTSNode:
    def __init__(self, state, parent=None, move=None):
        self.state = state
        self.parent = parent
        self.move = move
        self.children = []
        self.wins = 0
        self.visits = 0
        self.untried_moves = state.get_legal_moves()

    def uct_select_child(self):
        c = 1.41
        return max(self.children, key=lambda child: 
            (child.wins / child.visits) + c * math.sqrt(math.log(self.visits) / child.visits)
        )

    def expand(self):
        move = self.untried_moves.pop()
        next_state = self.state.apply_move(move)
        child = MCTSNode(next_state, parent=self, move=move)
        self.children.append(child)
        return child

    def backpropagate(self, result):
        self.visits += 1
        self.wins += result
        if self.parent:
            self.parent.backpropagate(result)

def run_mcts(root_state, iterations=1000):
    root = MCTSNode(root_state)
    for _ in range(iterations):
        node = root
        state = GameState(root_state.current_total)

        # Select
        while not node.untried_moves and node.children:
            node = node.uct_select_child()
            state = state.apply_move(node.move)

        # Expand
        if node.untried_moves:
            node = node.expand()
            state = state.apply_move(node.move)

        # Simulate
        while not state.is_terminal():
            state = state.apply_move(random.choice(state.get_legal_moves()))

        # Backpropagate
        node.backpropagate(state.get_result())

    return max(root.children, key=lambda c: c.visits).move

# --- CI/CD Automated Test ---
if __name__ == '__main__':
    # Game: Start at 3. Target is 5. Legal moves: +1, +2.
    # The optimal move is clearly +2.
    best_move = run_mcts(GameState(3), iterations=500)
    assert best_move == 2, f"AI made wrong move: {best_move}"
    print("Python MCTS Test Passed!")

class GameState {
    constructor(public total: number = 0) {}
    getLegalMoves(): number[] { return this.total < 5 ? [1, 2] : []; }
    applyMove(move: number): GameState { return new GameState(this.total + move); }
    isTerminal(): boolean { return this.total >= 5; }
    getResult(): number { return this.total === 5 ? 1.0 : 0.0; }
}

class MCTSNode {
    children: MCTSNode[] = [];
    wins: number = 0;
    visits: number = 0;
    untriedMoves: number[];

    constructor(public state: GameState, public parent: MCTSNode | null = null, public move: number | null = null) {
        this.untriedMoves = state.getLegalMoves();
    }

    uctSelectChild(): MCTSNode {
        const c = 1.41;
        return this.children.reduce((best, child) => {
            const uct = (child.wins / child.visits) + c * Math.sqrt(Math.log(this.visits) / child.visits);
            const bestUct = (best.wins / best.visits) + c * Math.sqrt(Math.log(this.visits) / best.visits);
            return uct > bestUct ? child : best;
        });
    }

    expand(): MCTSNode {
        const move = this.untriedMoves.pop()!;
        const child = new MCTSNode(this.state.applyMove(move), this, move);
        this.children.push(child);
        return child;
    }

    backpropagate(result: number): void {
        this.visits++;
        this.wins += result;
        if (this.parent) this.parent.backpropagate(result);
    }
}

function runMCTS(rootState: GameState, iterations: number = 1000): number {
    const root = new MCTSNode(rootState);
    for (let i = 0; i < iterations; i++) {
        let node = root;
        let state = new GameState(rootState.total);

        while (node.untriedMoves.length === 0 && node.children.length > 0) {
            node = node.uctSelectChild();
            state = state.applyMove(node.move!);
        }
        if (node.untriedMoves.length > 0) {
            node = node.expand();
            state = state.applyMove(node.move!);
        }
        while (!state.isTerminal()) {
            const moves = state.getLegalMoves();
            state = state.applyMove(moves[Math.floor(Math.random() * moves.length)]);
        }
        node.backpropagate(state.getResult());
    }
    return root.children.reduce((best, child) => child.visits > best.visits ? child : best).move!;
}

