            states = new List<State> { new State(0, -1) };
            last = 0;
            Size = 1;

            foreach (char c in text) {
                Extend(c);
            }
        }

        private void Extend(char c) {
            int cur = Size++;
            states.Add(new State(states[last].length + 1, 0));

            int p = last;
            while (p != -1 && !states[p].transitions.ContainsKey(c)) {
                states[p].transitions[c] = cur;
                p = states[p].link;
