                root = s;
                s.children.Add(r);
                SplitChild(s, 0, r);
                InsertNonFull(s, k);
            } else {
                InsertNonFull(r, k);
            }
        }

        private void InsertNonFull(BTreeNode node, int k) {
            int i = node.keys.Count - 1;

            if (node.leaf) {
                node.keys.Add(0); // make space
                while (i >= 0 && k < node.keys[i]) {
                    node.keys[i + 1] = node.keys[i];
                    i--;
                }
                node.keys[i + 1] = k;
            } else {
                while (i >= 0 && k < node.keys[i]) {
                    i--;
