                i++;

                BTreeNode child = node.children[i];
                if (child.keys.Count == 2 * t - 1) {
                    SplitChild(node, i, child);
                    if (k > node.keys[i]) {
                        i++;
                    }
                }
                InsertNonFull(node.children[i], k);
            }
