        private void SplitChild(BTreeNode parent, int i, BTreeNode fullChild) {
            BTreeNode newNode = new BTreeNode(fullChild.leaf);

            for (int j = 0; j < t - 1; j++) {
                newNode.keys.Add(fullChild.keys[t]);
                fullChild.keys.RemoveAt(t);
