        uint64_t timestamp = currentTimeMillis();

        if (timestamp < lastTimestamp) {
            throw runtime_error("Clock moved backwards.");
        }

        if (timestamp == lastTimestamp) {
            sequence = (sequence + 1) & SEQUENCE_MASK;
            if (sequence == 0) {
